function isoWeek(y,m,d){
  var date=new Date(Date.UTC(y,m-1,d)); var day=date.getUTCDay()||7;
  date.setUTCDate(date.getUTCDate()+4-day);
  var yearStart=new Date(Date.UTC(date.getUTCFullYear(),0,1));
  var week=Math.ceil((((date - yearStart)/86400000)+1)/7);
  return {year:date.getUTCFullYear(), week:week, dow:day};
}
function fromStr(s){ if(!/^\d{4}-\d{2}-\d{2}/.test(s||'')) return {error:'日期格式应为 YYYY-MM-DD'};
  var p=s.split('-'); return isoWeek(+p[0],+p[1],+p[2]); }
var DOW=['周一','周二','周三','周四','周五','周六','周日'];
var EXPORTS={isoWeek:isoWeek, fromStr:fromStr, DOW:DOW};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.WeekNumberForgePure = EXPORTS; }
